const curve = (a, b, c, d, t) => a * (1-t) ** 3 + 3 * b * t * (1-t) ** 2 + 3 * c * t * t * (1-t) + d * t ** 3;
const normalize = v => { const length = Math.hypot(...v) || 1; return v.map(x => x / length); };
