  const z=mix(.42,.96,random(slot+1)), angle=random(slot+19)*Math.PI*2, r=Math.sqrt(1-z*z);
  const point=center.map((v,i)=>v*z+r*(right[i]*Math.cos(angle)+up[i]*Math.sin(angle)));
